<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_valid($_POST['csrf_token']??null))$error='Session expired. Refresh and try again.';
 else{try{$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');if($action==='delete'){$q=$pdo->prepare('DELETE FROM contact_messages WHERE id=?');$q->execute([$id]);admin_flash('Message deleted.');}else{$status=(string)($_POST['status']??'');if(!in_array($status,['new','read','contacted','closed'],true))throw new RuntimeException('Invalid status.');$q=$pdo->prepare('UPDATE contact_messages SET status=? WHERE id=?');$q->execute([$status,$id]);admin_flash('Message status updated.');}header('Location: /admin/messages.php');exit;}catch(Throwable $e){$error='Could not update this message.';}}
}
$messages=$pdo->query('SELECT * FROM contact_messages ORDER BY FIELD(status,"new","read","contacted","closed"),created_at DESC')->fetchAll();$pageTitle='Messages';require __DIR__.'/includes/header.php';
?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><section class="admin-panel"><div class="panel-heading"><div><h2>Project requests</h2><p>Private enquiries submitted through the website contact form.</p></div></div><?php if(!$messages):?><p class="empty-admin">No contact messages yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>CONTACT</th><th>PROJECT DETAILS</th><th>MESSAGE</th><th>STATUS</th><th>DATE</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($messages as $m):?><tr><td><strong><?=e($m['name'])?></strong><small><a href="mailto:<?=e($m['email'])?>"><?=e($m['email'])?></a></small><small><?=e($m['phone'])?></small></td><td><?=e($m['service'])?><small><?=e($m['budget'])?></small></td><td class="message-cell"><?=nl2br(e($m['message']))?></td><td><span class="status status-<?=e($m['status'])?>"><?=e($m['status'])?></span></td><td><?=e($m['created_at'])?></td><td><form method="post" class="inline-admin"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$m['id']?>"><select name="status"><option value="new" <?=$m['status']==='new'?'selected':''?>>New</option><option value="read" <?=$m['status']==='read'?'selected':''?>>Read</option><option value="contacted" <?=$m['status']==='contacted'?'selected':''?>>Contacted</option><option value="closed" <?=$m['status']==='closed'?'selected':''?>>Closed</option></select><button name="action" value="status">Update</button></form><form method="post" onsubmit="return confirm('Delete this message?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$m['id']?>"><button class="danger-link" name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>
